def transform(grid):
    # Objects are separated into nonzero 3x3 blocks by zero background.
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        stack.append((ny,nx))
            rs = [y for y, x in cells]
            cs = [x for y, x in cells]
            y0, y1, x0, x1 = min(rs), max(rs), min(cs), max(cs)
            comps.append((y0, x0, [[grid[y][x] for x in range(x0, x1+1)] for y in range(y0, y1+1)]))
    # The desired patch is the unique object using three colors.
    for _, _, patch in comps:
        if len({v for row in patch for v in row}) == 3:
            return patch
    return comps[0][2]
